head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDDST60204";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jlddst60204.onpageload' });
    }
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function () {
    $c.util.getComponent('ipt_method').setValue("searchCorpListAll");
    $c.util.getComponent('ipt_forward').setValue("corpListAll");
    const comnm = (scwin.openerScwin()["AKCKwd"] && (scwin.openerScwin()["AKCKwd"]).getValue ? (scwin.openerScwin()["AKCKwd"]).getValue() : (scwin.openerComp("AKCKwd").getValue ? scwin.opener().getComponentById("AKCKwd").getValue() : ''));
    if (comnm !== "") {
        $c.util.getComponent('ipt_corpNameTmp').setValue(comnm);
        scwin.reflectCorpName();
    }
    await scwin.fnSearchInit();
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        await scwin.init();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst60204.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
